}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 color;
in vec2 uv0;
layout(std140) uniform Constant {
  vec4 baseColor;
  vec4 fireColor1;
  vec4 fireColor2;
  vec2 noiseScale;
  float baseHeight;
  float fireIntensity;
  float fireSpeed;
};
#if USE_TEXTURE
  uniform sampler2D cc_spriteTexture;
#endif
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}
float noise(vec2 x) {
    vec2 i = floor(x);
    vec2 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(vec2 p) {
    float f = 0.0;
    float w = 0.5;
    for (int i = 0; i < 5; i++) {
        f += w * noise(p);
        p *= 2.0;
        w *= 0.5;
    }
    return f;
}
vec4 frag () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
    o *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
    #if IS_GRAY
      float gray  = 0.2126 * o.r + 0.7152 * o.g + 0.0722 * o.b;
      o.r = o.g = o.b = gray;
    #endif
  #endif
  o *= color;
  ALPHA_TEST(o);
  float y_pos = 1.0 - uv0.y;
  float TIME = cc_time.x * fireSpeed;
  vec2 p1 = vec2(uv0.x * noiseScale.x, uv0.y * noiseScale.y - TIME);
  float n1 = fbm(p1);
  vec2 p2 = vec2(uv0.x * noiseScale.x * 1.5, uv0.y * noiseScale.y * 1.5 - TIME * 1.3);
  float n2 = fbm(p2);
  float n = (n1 + n2) * 0.5;
  float fire_dist = y_pos - baseHeight;
  float maxFireHeight = 1.0 - baseHeight;
  vec4 finalColor = vec4(0.0);
  if (fire_dist <= 0.0) {
      finalColor = baseColor;
  } else {
      if (fireIntensity > 0.0) {
          float norm_dist = fire_dist / (maxFireHeight * fireIntensity + 0.0001);
          float density = n - norm_dist;
          if (density > 0.0) {
              float color_mix = smoothstep(0.0, 0.4, density);
              vec4 flameColor = mix(fireColor2, fireColor1, color_mix);
              float base_mix = smoothstep(0.0, 0.15, norm_dist);
              flameColor = mix(baseColor, flameColor, base_mix);
              finalColor = flameColor;
              finalColor.a = smoothstep(0.0, 0.05, density);
          }
      }
  }
  finalColor.a *= o.a;
  return finalColor;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

